/**
 * 讀取檔案內容（PDF/影像以雲端硬碟 OCR 轉成暫存 Google 文件後匯出純文字，再刪除暫存檔）
 * Word 檔亦可轉換。結果快取 6 小時，避免重複 OCR。
 */
function impText_(f) {
  const ck = 'imptxt|' + f.id, cache = CacheService.getScriptCache(), hit = cache.get(ck);
  if (hit != null) return hit;
  const cp = JSON.parse(driveFetch_('https://www.googleapis.com/drive/v3/files/' + f.id + '/copy?fields=id&ocrLanguage=zh-TW&supportsAllDrives=true', {
    method: 'post', contentType: 'application/json',
    payload: JSON.stringify({ name: '_ocr_暫存_' + f.id, mimeType: 'application/vnd.google-apps.document', parents: [impFolder_()] }) }).getContentText());
  let txt = '';
  try { txt = driveFetch_('https://www.googleapis.com/drive/v3/files/' + cp.id + '/export?mimeType=text/plain').getContentText(); }
  finally { try { driveFetch_('https://www.googleapis.com/drive/v3/files/' + cp.id, { method: 'delete' }); } catch (e) { } }
  txt = txt.replace(/\r/g, '').slice(0, 90000);
  try { cache.put(ck, txt, 21600); } catch (e) { }
  return txt;
}
/** 從內容擷取：工程名稱、日期（民國／西元各種寫法 → yyyy-mm-dd）、查核類別線索 */
function impParse_(txt) {
  const t = String(txt || '').normalize('NFKC');
  const nm = (t.match(/工程名稱\s*[:：]?\s*([^\n]{4,80})/) || [])[1] || '';
  const ds = {}, add = (y, m, d) => { y = +y; if (y < 1000) y += 1911; m = +m; d = +d; if (y >= 2015 && y <= 2035 && m >= 1 && m <= 12 && d >= 1 && d <= 31) ds[y + '-' + ('0' + m).slice(-2) + '-' + ('0' + d).slice(-2)] = 1; };
  let m; const re1 = /(\d{3,4})\s*年\s*(\d{1,2})\s*月\s*(\d{1,2})\s*日/g; while ((m = re1.exec(t))) add(m[1], m[2], m[3]);
  const re2 = /(?<!\d)(1\d{2}|20\d{2})[.\/-](\d{1,2})[.\/-](\d{1,2})(?!\d)/g; while ((m = re2.exec(t))) add(m[1], m[2], m[3]);
  const re3 = /(?<!\d)(1[01]\d)(\d{2})(\d{2})(?!\d)/g; while ((m = re3.exec(t))) add(m[1], m[2], m[3]);
  const kd = (t.match(/(?:查核|督導)日期\s*[:：]?\s*([^\n]{6,20})/) || [])[1] || '';
  const kdd = []; if (kd) { const r = impParse_dates_(kd); r.forEach(x => kdd.push(x)); }
  let kind = '';
  if (/公共工程委員會/.test(t)) kind = '中央查核';
  else if (/督導/.test(t) && !/查核/.test(t)) kind = '督導';
  return { 名稱: nm.trim(), 日期: Object.keys(ds), 查核日期: kdd, 類別: kind };
}
function impParse_dates_(s) {
  const out = [], m = String(s).match(/(\d{3,4})\s*[年.\/-]\s*(\d{1,2})\s*[月.\/-]\s*(\d{1,2})/);
  if (m) { let y = +m[1]; if (y < 1000) y += 1911; out.push(y + '-' + ('0' + m[2]).slice(-2) + '-' + ('0' + m[3]).slice(-2)); }
  return out;
}
/**
 * 依「檔案內容」找對應案件（檔名無法確定時使用）
 *   工程名稱出現在內容中 → 候選；多筆時以內容中的查核日期／任一日期與案件日期相符者篩選
 *   唯一候選且（日期相符或案件尚無日期）→ 可確定
 */
function impMatchText_(txt, cases) {
  const info = impParse_(txt), tk = impKey_(txt);
  let hit = cases.filter(c => { const k = impKey_(c.工程名稱); return k.length >= 6 && tk.indexOf(k) >= 0; });
  if (hit.length > 1) { const L = Math.max.apply(null, hit.map(c => impKey_(c.工程名稱).length)); const lg = hit.filter(c => impKey_(c.工程名稱).length === L); if (lg.length >= 1) hit = lg; }
  const key = info.查核日期.length ? info.查核日期 : info.日期;
  if (hit.length > 1) { const sd = hit.filter(c => key.indexOf(c.日期) >= 0); if (sd.length) hit = sd; }
  if (hit.length > 1) { const sd = hit.filter(c => info.日期.indexOf(c.日期) >= 0); if (sd.length) hit = sd; }
  if (hit.length > 1 && info.類別) { const q = hit.filter(c => c.項目 === info.類別); if (q.length) hit = q; }
  hit.sure = hit.length === 1 && (!hit[0].日期 || info.日期.indexOf(hit[0].日期) >= 0);
  hit.info = info;
  return hit;
}
/** 內容摘要（寫入待對應說明，方便人工判斷或補登案件） */
function impInfoNote_(info) {
  return '內容：' + [info.名稱 && ('工程名稱 ' + info.名稱), (info.查核日期[0] || '') && ('查核日期 ' + info.查核日期[0]), info.類別 && ('疑為' + info.類別)].filter(Boolean).join('；');
}
/** 檢視來源檔內容（系統維護）：回傳擷取資訊與前段文字 */
function apiImpPeek(args) {
  const r = findRows_('改善來源', '來源ID', String(args.srcId || ''))[0];
  if (!r) throw new Error('找不到來源檔');
  const txt = impText_({ id: r.來源ID });
  const all = readTable_('案件').filter(c => c.狀態 !== ST_CANCEL && c.狀態 !== ST_VOID);
  const hit = impMatchText_(txt, all);
  return { 檔名: r.檔名, info: hit.info, 候選: hit.map(c => ({ id: c.案件編號, 日期: c.日期, 項目: c.項目, 工程名稱: c.工程名稱 })), sure: hit.sure, text: txt.slice(0, +(args.len || 4000)) };
}
/** 待對應者重新以內容判斷（系統維護）；可確定者自動匯入 */
function apiImpRecheck(args, user) {
  const lock = LockService.getScriptLock(); lock.waitLock(30000);
  try {
    const all = readTable_('案件').filter(c => c.狀態 !== ST_CANCEL && c.狀態 !== ST_VOID);
    const now = nowStr_(), t0 = Date.now(), rep = { checked: 0, auto: 0, pending: 0, list: [] };
    readTable_('改善來源').filter(r => r.狀態 === '待對應').forEach(r => {
      if (Date.now() - t0 > 240000) return;
      rep.checked++;
      const res = impContentResolve_({ id: String(r.來源ID), name: String(r.檔名), size: r.大小 }, all, user || { Email: 'auto' }, now, args.dryRun);
      Object.assign(r, res.row); if (!args.dryRun) writeRow_('改善來源', r);
      if (res.row.狀態 === '已匯入' || res.sure) { rep.auto++; rep.list.push((res.caseId || '') + ' ' + r.檔名); } else { rep.pending++; rep.list.push('待對應 ' + r.檔名 + '［' + res.row.說明 + '］'); }
    });
    return rep;
  } finally { lock.releaseLock(); }
}
/** 以內容判斷單一檔案；可確定且非 dryRun 則匯入。回傳要寫回改善來源的欄位 */
function impContentResolve_(f, all, user, now, dryRun) {
  let txt = '';
  try { txt = impText_(f); } catch (e) { return { row: { 說明: '無法讀取內容：' + e.message, 處理時間: now } }; }
  const hit = impMatchText_(txt, all);
  const note = impInfoNote_(hit.info);
  if (hit.sure) {
    if (dryRun) return { sure: true, caseId: hit[0].案件編號, row: {} };
    const r = impCopy_(f, hit[0], user, now);
    log_(user.Email, '改善檔案依內容匯入', hit[0].案件編號, { 來源: f.name, 檔名: r.name });
    return { caseId: hit[0].案件編號, row: { 狀態: '已匯入', 案件編號: hit[0].案件編號, 系統檔案ID: r.id, 說明: r.name + '（依內容判斷' + (hit[0].日期 ? '' : '；案件尚無日期') + '）', 處理時間: now } };
  }
  return { row: { 候選: hit.slice(0, 5).map(c => c.案件編號).join(','), 說明: (hit.length ? (hit.length > 1 ? '內容比對有多個候選' : '內容日期與案件不符') : '系統無對應案件，請補登') + '｜' + note, 處理時間: now } };
}
  const all = readTable_('案件').filter(c => c.狀態 !== ST_CANCEL && c.狀態 !== ST_VOID), cases = all.filter(c => c.日期);
    // 檔名無法確定 → 打開檔案以內容判斷（OCR）
    if (!hit.sure && Date.now() - t0 < 200000) {
      const res = impContentResolve_(f, all, user || { Email: 'auto' }, now, args.dryRun);
      if (res.row.狀態 === '已匯入' || res.sure) { if (f.md5) have[f.md5] = 1; Object.assign(row, res.row); rep.auto++; rep.auto_list.push((res.caseId || '') + ' ' + f.name + '（依內容）'); rows.push(row); return; }
      Object.assign(row, res.row);
    }
  impPeek: [apiImpPeek, ['系統維護']],
  impRecheck: [apiImpRecheck, ['系統維護']],
